        listOf("44a28dad6fafc9ea85f8434ba4edf7e43715e181032b42e73cd7be33f128bfea", "5331e16354993d61e8daa1eb", "b1fbaad7fa897878d687b201", "db066ff4b93b92", "74aa3d868509820c52be635bb5446ffa0441aa4bed81e6"),
        listOf("e24eca36649f951390e92b2508061c1b9fed2958fa24b307070a23b1a4a20ab2", "11bc0b10db97c35d33d1f4d1", "88e4aa10e1dec1eab6f1621b", "3f34341c0808f3d9e9cfc0a216d3c0a1a1497a192119cac1a5344b51566c42055941ee480cb7c25ee952c4f69a8079d9499ebe07c969076f84c5195878b40c89", "e6d85e28aad181dd8835674929b4ab4e5a49a5c2934f149cb5e31de5f7cc32a03d10d25bd1f74b66f167822ebf2bc789193eebf02d5aa1e404a60892abb4172709c3e8775e1f22130552257162ed8bda"),
        listOf("9037b6dcd31793d1492b6f00863349c3c0fa0d01597d187db1cbd32ff77e9758", "f5d4834293f12848d036f0b3", "3b7f2a1cf0a2c4147dc9fdb2", "8fc91aa0535b1866ed65e4e3be166ce3a5065f344d436de68b802b61fbe2a13bf175208898c1b0c09aa5085994538527ded773a98dbd522b7670b0c541943b205576a4e2b23c8131444dc1b4d3d79e27b927f93fb9539a8559293c53f43042f9f4bafe1a2af6a81a326226fb25cb4dbb4c6f46321ba3e91b4734e26376080366da", "0fff71e75d072225df6b7e1820ab54e41512af4679f2748b1e8e4ec8346bb33ed274572cabbcdf6d1412361fb5ecf2eb70f913365739a23f58f09238ce4b49cc4ba4232557bb935f9a55d89b3efafcfac3be71fb3be63643c2065832331639f2445334d742d4294faac001797fc61296ab3bfd9ca1770eb9bf02b067bd35792773faa722b752201c5ac936140195ddd6e3"),
    )

    @Test fun chacha20Poly1305MatchesOpenSsl() {
        for ((key, nonce, aad, pt, ct) in chachaCases) {
            assertEquals(ct, ChaCha20Poly1305.seal(h(key), h(nonce), h(pt), h(aad)).toHex())
            assertContentEquals(h(pt), ChaCha20Poly1305.open(h(key), h(nonce), h(ct), h(aad)))
        }
    }

