    @Test fun xchacha20Poly1305MatchesLibsodium() {
        for ((key, nonce, aad, pt, ct) in xchachaCases) {
            assertEquals(ct, XChaCha20Poly1305.seal(h(key), h(nonce), h(pt), h(aad)).toHex(), "length ${pt.length / 2}")
            assertContentEquals(h(pt), XChaCha20Poly1305.open(h(key), h(nonce), h(ct), h(aad)))
        }
    }

    @Test fun tamperingWrongKeyOrWrongAadIsRejected() {
        val (key, nonce, aad, _, ct) = xchachaCases[8]
        val bytes = h(ct)
        for (i in listOf(0, bytes.size / 2, bytes.size - 1)) {
            val bad = bytes.copyOf().also { it[i] = (it[i].toInt() xor 1).toByte() }
            assertFailsWith<AuthenticationException> { XChaCha20Poly1305.open(h(key), h(nonce), bad, h(aad)) }
        }
        val otherKey = h(key).also { it[0] = (it[0].toInt() xor 0x80).toByte() }
        assertFailsWith<AuthenticationException> { XChaCha20Poly1305.open(otherKey, h(nonce), bytes, h(aad)) }
        assertFailsWith<AuthenticationException> { XChaCha20Poly1305.open(h(key), h(nonce), bytes, h(aad) + byteArrayOf(0)) }
        assertFailsWith<AuthenticationException> { XChaCha20Poly1305.open(h(key), h(nonce), ByteArray(3), h(aad)) }
    }

    @Test fun sha256Fips() {
        assertEquals("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", Sha256.digest("".encodeToByteArray()).toHex())
        assertEquals("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad", Sha256.digest("abc".encodeToByteArray()).toHex())
        assertEquals("248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1", Sha256.digest("abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq".encodeToByteArray()).toHex())
        assertEquals("41edece42d63e8d9bf515a9ba6932e1c20cbc9f5a5d134645adb5db1b9737ea3", Sha256.digest("a".repeat(1000).encodeToByteArray()).toHex())
        // Lengths around the 55/56/64-byte padding boundaries.
        val zeros = mapOf(55 to "02779466cdec163811d078815c633f21901413081449002f24aa3e80f0b88ef7", 56 to "d4817aa5497628e7c77e6b606107042bbba3130888c5f47a375e6179be789fbb", 63 to "c7723fa1e0127975e49e62e753db53924c1bd84b8ac1ac08df78d09270f3d971", 64 to "f5a5fd42d16a20302798ef6ed309979b43003d2320d9f0e8ea9831a92759fb4b", 65 to "98ce42deef51d40269d542f5314bef2c7468d401ad5d85168bfab4c0108f75f7", 119 to "f616b0d54e78571a9611f343c9f8e022e859e920381ab0e4d3da01e193a7bd7e", 120 to "6edd9f6f9cc92cded36e6c4a580933f9c9f1b90562b46903b806f21902a1a54f")
        for ((n, d) in zeros) assertEquals(d, Sha256.digest(ByteArray(n)).toHex(), "zeros($n)")
    }

    @Test fun secureRandomIsTheRequestedSizeAndNotConstant() {
        assertEquals(32, secureRandomBytes(32).size)
        assertEquals(0, secureRandomBytes(0).size)
        assertNotEquals(secureRandomBytes(32).toHex(), secureRandomBytes(32).toHex())
    }
}
